namespace ghidra.trace.model.bookmark;

using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.lang;
using ghidra.trace.model;
using ghidra.trace.model;
using ghidra.trace.model.guest;
using ghidra.trace.util;

public interface TraceBookmarkSpace : TraceBookmarkOperations {
	Trace getTrace();

	AddressSpace getAddressSpace();

	TraceBookmark addBookmark(Lifespan lifespan, Register register,
			TraceBookmarkType type, string category, string comment) {
		TracePlatform host = getTrace().getPlatformManager().getHostPlatform();
		AddressRange range = host.getConventionalRegisterRange(getAddressSpace(), register);
		return addBookmark(lifespan, range.getMinAddress(), type, category, comment);
	}

	Iterable<TraceBookmark> getBookmarksEnclosed(Lifespan lifespan,
			Register register) {
		return getBookmarksEnclosed(lifespan, TraceRegisterUtils.rangeForRegister(register));
	}

	Iterable<TraceBookmark> getBookmarksIntersecting(Lifespan lifespan,
			Register register) {
		return getBookmarksIntersecting(lifespan, TraceRegisterUtils.rangeForRegister(register));
	}
}
